type User = { name: string; email?: string };

function greet(u: User | null) {
  // u.name; // error under strictNullChecks
  if (!u) return "no user";
  return u.name + (u.email ? ` <${u.email}>` : "");
}

// Non-null assertion — no runtime check:
function risky(u: User | null) {
  return u!.name; // compiles — can throw at run time
}

function greet(u) {
  if (!u) return "no user";
  return u.name + (u.email ? ` <${u.email}>` : "");
}

greet(JSON.parse('{"name":"Ada"}')); // works
greet(null); // "no user"
greet(JSON.parse("{}")); // undefined name concat — no TS to warn

function requireString(value, field) {
  if (value == null) throw new TypeError(`${field} is nullish`);
  if (typeof value !== "string") throw new TypeError(`${field} must be string`);
  return value;
}

function mapDto(raw) {
  return {
    id: requireString(raw.id, "id"),
    name: requireString(raw.name, "name"),
  };
}
